import React, { createContext, useState, useEffect } from "react";

export const UserContext = createContext();

export const UserProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [goals, setGoals] = useState([]);

  useEffect(() => {
    if (token && !user) {
      // Optionally decode token for user info
      const payload = JSON.parse(atob(token.split(".")[1]));
      setUser({ id: payload.id, email: payload.email });
    }
  }, [token, user]);

  const login = async (email, password) => {
    setLoading(true);
    setError("");
    try {
      const res = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Login failed");
      setUser(data.user);
      setToken(data.token);
      localStorage.setItem("token", data.token);

      // Fetch goals after successful login
      const goalsRes = await fetch("/api/goals", {
        method: "GET",
        headers: { "Authorization": `Bearer ${data.token}` },
      });
      const userGoals = await goalsRes.json();
      console.log("Fetched goals:", userGoals);
      setGoals(userGoals);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const register = async (email, password) => {
    setLoading(true);
    setError("");
    try {
      const res = await fetch("/api/auth/register", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Registration failed");
      setUser(data.user);
      setToken(data.token);
      localStorage.setItem("token", data.token);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const logout = () => {
    setUser(null);
    setToken("");
    localStorage.removeItem("token");
    setGoals([]);
  };

  return (
    <UserContext.Provider value={{ user, token, loading, error, login, register, logout, goals, setGoals }}>
      {children}
    </UserContext.Provider>
  );
};
